def normalize_totp_secret(secret: str) -> bytes:
    compact = "".join(secret.split()).upper().replace("-", "")
    pad = "=" * ((8 - len(compact) % 8) % 8)
    return base64.b32decode(compact + pad, casefold=True)


def totp_code(secret: str, at: float | None = None, digits: int = 6, period: int = 30) -> str:
    """和密码 app 同一套：30 秒、6 位、HMAC-SHA1。"""
    key = normalize_totp_secret(secret)
    counter = int((time.time() if at is None else at) // period)
    digest = hmac.new(key, struct.pack(">Q", counter), hashlib.sha1).digest()
    offset = digest[-1] & 0x0F
    binary = struct.unpack(">I", digest[offset:offset + 4])[0] & 0x7FFFFFFF
    return str(binary % (10 ** digits)).zfill(digits)


def read_mfa_secret(account: str) -> str:
    proc = subprocess.run(
        [
            "/usr/bin/security", "find-generic-password",
            "-a", account, "-s", MFA_KEYCHAIN_SERVICE, "-w",
        ],
        capture_output=True,
        text=True,
    )
    secret = (proc.stdout or "").strip()
    if proc.returncode != 0 or not secret:
        raise RuntimeError(
            "人效通验证码密钥不在登录钥匙串。密码 app 里跳动的 6 位码脚本读不到，"
